SELECT p.id AS pid, e.id, e.wallet_position_id, e.symbol, e.event_type, e.old_value_usdt, e.new_value_usdt, e.market_price_usdt, e.occurred_at, LEFT(e.reason, 600) AS reason FROM crypto_ai.paper_position p JOIN crypto_ai.position_management_event e ON e.symbol = p.symbol AND e.occurred_at BETWEEN p.opened_at - INTERVAL 1 MINUTE AND p.closed_at + INTERVAL 1 MINUTE WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, e.occurred_at LIMIT 300;